let todos: Todo[] = [];

export function add(title: string, priority: Priority = "normal"): Todo {
  const t = { id: nextId++, title: title.trim(), done: false, priority };
  todos.push(t);
  return t;
}

export function complete(id: number): boolean {
  const t = todos.find((x) => x.id == id);
  if (!t) return false;
  t.done = true;
  return true;
}

export function clearDone(): number {
  const previousLength = todos.length;
  todos = todos.filter((todo) => !todo.done);
  return previousLength - todos.length;
}

export function isEmpty(): boolean {
  return todos.length === 0;
}

export function list(filter: Filter = {}): Todo[] {
  return filterTodos(todos, filter);
}

export function count(filter: Filter = {}): number { return list(filter).length; }

export function get(id: number): Todo | undefined {
  return todos.find((x) => x.id === id);
}

export function reset(): void {
  todos.length = 0;
  nextId = 1;
}
