assert.equal(afterFirstRemoval.includes(first), false);
assert.strictEqual(afterFirstRemoval[0], second);
assert.strictEqual(afterFirstRemoval[1], third);
assert.strictEqual(get(first.id), second);
assert.strictEqual(get(third.id), third);
assert.equal(snapshot.length, 3);
assert.deepEqual(snapshot.map(({ id, title }) => [id, title]), [[1, "first"], [1, "second"], [3, "third"]]);
assert.strictEqual(snapshot[0], first);
assert.strictEqual(snapshot[1], second);
assert.strictEqual(snapshot[2], third);
console.log("PASS first removal: removed only the first match; duplicate, survivor order/identity, get(), and old snapshot verified");

assert.equal(removeTodo(first.id), true);
const afterSecondRemoval = list();
assert.deepEqual(afterSecondRemoval, [third]);
assert.strictEqual(afterSecondRemoval[0], third);
assert.strictEqual(get(first.id), undefined);
console.log("PASS second removal: remaining duplicate removed by ID");

assert.equal(removeTodo(first.id), false);
assert.deepEqual(list(), afterSecondRemoval);
