{"type":"message","id":"a1af422b","parentId":"c71bc204","timestamp":"2026-09-25T10:00:14.292Z","message":{"role":"toolResult","toolCallId":"call_qp5wHQUfCnOrg1CvgCrAEkAF|fc_037b53db53fa1d61016ab6462e149887d0a380193147142f4e","toolName":"read","content":[{"type":"text","text":"import { beforeEach, expect, test } from "bun:test";
import { add, clearDone, complete, count, get, isEmpty, list, removeTodo, reset } from "../src/store";

beforeEach(reset);

test("add then list returns the item", () => {
  add("a");
  expect(list()).toEqual([{ id: 1, title: "a", done: false, priority: "normal" }]);
});

test("add accepts an explicit priority", () => {
  expect(add("a", "high").priority).toBe("high");
});

test("add trims title edges and preserves interior whitespace", () => {
  const added = add(" \tpay  the\tbill \n ");
  expect(added.title).toBe("pay  the\tbill");
  expect(list()[0]?.title).toBe("pay  the\tbill");
});

test("add accepts a title that trims to empty", () => {
  const added = add(" \t ");
  expect(added.title).toBe("");
  expect(list()[0]?.title).toBe("");
});

test("complete marks the item done", () => {
  add("a");
  complete(1);
  expect(list({ done: true }).map((t) => t.id)).toEqual([1]);
});

test("open filter returns only undone items", () => {
  add("a");
  add("b");
  complete(1);
  expect(list({ done: false }).map((t) => t.id)).toEqual([2]);
});

test("high filter returns only high-priority items", () => {
  add("a", "high");
  add("b");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1]);
});

test("empty filter returns every item", () => {
  add("a");
  add("b");
  expect(list({}).map((t) => t.id)).toEqual([1, 2]);
});

test("isEmpty reports whether the store contains todos", () => {
  expect(isEmpty()).toBe(true);
  add("a");
  expect(isEmpty()).toBe(false);
});

test("count returns zero for an empty store", () => {
  expect(count()).toBe(0);
});

test("count includes completed todos in the total", () => {
  add("a");
  add("b");
  complete(1);
  expect(count()).toBe(2);
});

test("count applies a filter", () => {
  add("a", "high");
  add("b", "low");
  expect(count({ priority: "high" })).toBe(1);
});

test("count combines done and priority filters", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(count({ done: false, priority: "low" })).toBe(1);
});

test("count returns zero when no todos match", () => {
  add("a", "normal");
  expect(count({ priority: "high" })).toBe(0);
});

test("list filters by priority", () => {
  add("a", "high");
  add("b", "low");
  add("c", "high");
  expect(list({ priority: "high" }).map((t) => t.id)).toEqual([1, 3]);
});

test("list combines filter fields", () => {
  add("a", "low");
  add("b", "low");
  add("c", "high");
  complete(1);
  expect(list({ done: false, priority: "low" }).map((t) => t.id)).toEqual([2]);
});

test("list returns a new array", () => {
  add("a");
  list().pop();
  expect(list().length).toBe(1);
});

test("complete on a missing id returns false", () => {
  expect(complete(99)).toBe(false);
});

test("completing twice keeps the item done", () => {
  add("a");
  complete(1);
  complete(1);
  expect(list()).toEqual([{ id: 1, title: "a", done: true, priority: "normal" }]);
});

test("reset restarts ids at 1", () => {
  add("a");
  add("b");
  reset();
  expect(add("c").id).toBe(1);
});

test("get returns the item by id or undefined", () => {
  add("a");
  expect(get(1)?.title).toBe("a");
  expect(get(2)).toBeUndefined();
});

test("removeTodo removes an existing item and returns true", () => {
  add("keep");
  add("remove");

  expect(removeTodo(2)).toBe(true);
  expect(get(2)).toBeUndefined();
  expect(removeTodo(2)).toBe(false);
});

test("removeTodo returns false for a missing id without changing the store", () => {
  add("keep");

  expect(removeTodo(99)).toBe(false);
  expect(list()).toEqual([
    { id: 1, title: "keep", done: false, priority: "normal" },
  ]);
});

test("removeTodo preserves unrelated todos and their order", () => {
  const first = add("first", "low");
  const removed = add("remove", "high");
  const last = add("last");
  complete(last.id);

  expect(removeTodo(removed.id)).toBe(true);
  expect(list()).toEqual([
    { id: 1, title: "first", done: false, priority: "low" },
    { id: 3, title: "last", done: true, priority: "normal" },
  ]);
  expect(get(first.id)).toBe(first);
  expect(get(last.id)).toBe(last);
});

test("removeTodo removes only the first item with a duplicate ID", () => {
  const first = add("first", "low");
  const duplicate = add("duplicate", "high");
  const last = add("last");
  duplicate.id = first.id;

  expect(removeTodo(first.id)).toBe(true);

  const survivors = list();
  expect(survivors).toEqual([
    { id: 1, title: "duplicate", done: false, priority: "high" },
    { id: 3, title: "last", done: false, priority: "normal" },
  ]);
  expect(get(first.id)).toBe(duplicate);
  expect(survivors[0]).toBe(duplicate);
  expect(survivors[1]).toBe(last);
});

test("removing todos updates count, emptiness, and the next ID", () => {
  const first = add("first");
  const second = add("second");
  const survivor = add("survivor");
  expect(count()).toBe(3);
  expect(removeTodo(first.id)).toBe(true);
  expect(count()).toBe(2);
  expect(isEmpty()).toBe(false);

  const next = add("after removal");
  expect(next.id).toBe(4);
  expect(removeTodo(second.id)).toBe(true);
  expect(removeTodo(survivor.id)).toBe(true);
  expect(removeTodo(next.id)).toBe(true);
  expect(count()).toBe(0);
  expect(isEmpty()).toBe(true);
});

